export function translateExact(text: string, lang: Lang): string | null {
  const hit = M[text];
  if (!hit) return null;
  if (lang === "HU") return hit[0];
  if (lang === "DA") return hit[1];
  if (lang === "DE") return hit[2];
  return text;
}
